import React from 'react'

/*
 * Ikony převzaté ze starého webu (Grails) — jediné místo, odkud si je berou
 * sekce „Příprava do …" (preparation-section) i panel „Praktické informace"
 * (practical-info-links). Zdroje: assets/images/affil/*.svg,
 * assets/images/information/*.svg, base64 pozadí v kickstart.css a SVG font
 * Glyphicons (silnice). Všechny kreslí přes `currentColor`, ať jdou barvit
 * z místa použití; bílé části (křížek v srdci, peřiny postele) zůstávají bílé.
 * Souřadnice cest jsou zaokrouhlené podle měřítka viewBoxu (vizuálně ověřeno
 * proti originálu) — plné znění je v git historii, kdyby bylo někdy potřeba.
 */

export interface IconProps {
  height: number
}

